def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Tile the occupied cells with 2x2 squares (color 1) and L-triominoes.
    # L color is determined by the missing corner of its 2x2 bounding box.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            pieces.append((box, 1))
            for missing, color in [
                ((r, c), 2),          # missing top-left
                ((r + 1, c), 3),      # missing bottom-left
                ((r, c + 1), 4),      # missing top-right
                ((r + 1, c + 1), 2),  # missing bottom-right
            ]:
                pieces.append((box - {missing}, color))

    options = {cell: [] for cell in cells}
    for shape, color in pieces:
        if shape <= cells:
            for cell in shape:
                options[cell].append((shape, color))

    def solve(left):
        if not left:
            return True
        # Choose the most constrained remaining cell.
        cell = min(left, key=lambda p: sum(shape <= left for shape, _ in options[p]))
        for shape, color in options[cell]:
            if shape <= left:
                for r, c in shape:
                    out[r][c] = color
                if solve(left - shape):
                    return True
                for r, c in shape:
                    out[r][c] = 0
        return False

    solve(cells)
    return out
